PRAGMA foreign_keys=ON;
CREATE TABLE projects(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, name TEXT NOT NULL, created_at TEXT NOT NULL) STRICT;
CREATE TABLE specifications(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), document TEXT NOT NULL CHECK(json_valid(document)), UNIQUE(project_id,id)) STRICT;
CREATE TABLE test_plans(id TEXT PRIMARY KEY, spec_id TEXT NOT NULL UNIQUE REFERENCES specifications(id), document TEXT NOT NULL CHECK(json_valid(document))) STRICT;
CREATE TABLE app_versions(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), spec_id TEXT NOT NULL, parent_version_id TEXT, document TEXT NOT NULL CHECK(json_valid(document)), UNIQUE(project_id,id), FOREIGN KEY(project_id,spec_id) REFERENCES specifications(project_id,id), FOREIGN KEY(project_id,parent_version_id) REFERENCES app_versions(project_id,id)) STRICT;
CREATE TABLE job_records(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), spec_id TEXT REFERENCES specifications(id), version_id TEXT REFERENCES app_versions(id), kind TEXT NOT NULL CHECK(kind IN ('SPECIFY','GENERATE')), state TEXT NOT NULL CHECK(state IN ('QUEUED','RUNNING','COMPLETED','ERROR','CANCELLED')), phase TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), error TEXT, created_at TEXT NOT NULL, finished_at TEXT) STRICT;
CREATE TABLE verification_runs(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), app_version_id TEXT NOT NULL REFERENCES app_versions(id), document TEXT NOT NULL CHECK(json_valid(document))) STRICT;
CREATE TABLE requirement_results(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES verification_runs(id), requirement_id TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('PASS','FAIL','UNVERIFIED')), document TEXT NOT NULL CHECK(json_valid(document))) STRICT;
CREATE TABLE evidence_files(id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES verification_runs(id), path TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL, kind TEXT NOT NULL) STRICT;
CREATE TABLE human_acceptances(version_id TEXT PRIMARY KEY REFERENCES app_versions(id), owner_id TEXT NOT NULL, created_at TEXT NOT NULL) STRICT;
CREATE TRIGGER immutable_spec BEFORE UPDATE ON specifications BEGIN SELECT RAISE(ABORT,'Specifications are immutable; create a revision'); END;
CREATE TRIGGER immutable_plan BEFORE UPDATE ON test_plans BEGIN SELECT RAISE(ABORT,'Test plans are immutable'); END;
CREATE TRIGGER immutable_version BEFORE UPDATE ON app_versions WHEN json_extract(OLD.document,'$.buildStatus')!='PENDING' OR NEW.id!=OLD.id OR NEW.project_id!=OLD.project_id OR NEW.spec_id!=OLD.spec_id OR NEW.parent_version_id IS NOT OLD.parent_version_id OR json_extract(NEW.document,'$.files')!=json_extract(OLD.document,'$.files') OR json_extract(NEW.document,'$.sourceSha256')!=json_extract(OLD.document,'$.sourceSha256') OR json_extract(NEW.document,'$.configSha256')!=json_extract(OLD.document,'$.configSha256') OR json_extract(NEW.document,'$.buildStatus') NOT IN ('SUCCEEDED','FAILED') BEGIN SELECT RAISE(ABORT,'Final versions and source identity are immutable'); END;
PRAGMA user_version=1;
